const { discount } = require('./pricing');
function checkout(items, code) {
	let total = items.reduce((a, i) => a + i.price, 0);
	total = discount(total, code);
	return finalize(total, code);
}
function finalize(total, code) { return discount(total, code); }
module.exports = { checkout };
